あー、vim起動時にsessionのcallbackを書き換えているのか
```  listen(invoker: Invoker): Promise&lt;void&gt; {
    this.#session.replaceCallback(async function (message: VimMessage) {
      const [msgid, expr] = message;
      let ok = null;
      let err = null;
      try {
        ok = await dispatch(invoker, expr);
      } catch (e) {
        err = e;
      }
      if (msgid !== 0) {
        await this.reply(msgid, [ok, err]);
      } else if (err !== null) {
        console.error(err);
      }
    });
    return this.#listener;
  }```
